var import_crypto4 = require("crypto");
var planeAPool8 = getPool(config2.db.planeAUrl);
var popularCorridorRepository = new PopularCorridorRepository(planeAPool8);
var logger12 = createLogger("plane-a.popular-corridors");
var popularCorridorsRoutes = async (app) => {
  app.get("/api/popular-corridors", async (request, reply) => {
    try {
      recordSearch("popular", "corridors");
    } catch {
    }
    try {
      const corridors = await popularCorridorRepository.listPopularCorridors();
      if (!Array.isArray(corridors)) {
        logger12.error("popular_corridors_invalid_response", {
          type: typeof corridors
        });
        reply.code(500);
        return {
          error: "internal_error",
          message: "Invalid response from database"
        };
      }
      const cachePayload = JSON.stringify({ count: corridors.length, corridors });
      const etag = `"${(0, import_crypto4.createHash)("sha256").update(cachePayload).digest("hex")}"`;
      reply.header("Cache-Control", "public, max-age=60, stale-while-revalidate=120");
      reply.header("ETag", etag);
      const clientEtag = request.headers["if-none-match"];
      if (clientEtag && clientEtag.toLowerCase() === etag.toLowerCase()) {
        logger12.debug("popular_corridors_cache_hit", { etag });
        reply.code(304);
        return "";
      }
      logger12.debug("popular_corridors_success", {
        count: corridors.length,
        cache_miss: true
      });
      const transformedCorridors = corridors.map((c) => ({
        route: c.route,
        count24h: c.count_24h,
        topProvider: c.top_provider,
        feeRange: c.fee_range,
        speedRange: c.speed_range,
        bestFor: c.best_for
      }));
      return {
        success: true,
        timestamp: (/* @__PURE__ */ new Date()).toISOString(),
        updatedAt: (/* @__PURE__ */ new Date()).toISOString(),
        count: transformedCorridors.length,
        data: transformedCorridors,
        corridors: transformedCorridors
        // Keep for backward compatibility
      };
    } catch (error) {
      logger12.error("popular_corridors_failed", {
        error: error.message,
        stack: error.stack
      });
      reply.code(500);
      return {
        error: "internal_error",
        message: "Failed to fetch popular corridors"
      };
    }
  });
};

